/**
 * Customer Self-Service Portal.
 *
 * Accessible via a time-limited link generated by an agent:
 *   /portal/<token>
 *
 * The customer can:
 *   - View their booking details and status
 *   - Pay an outstanding invoice via Razorpay
 *   - Download their vouchers and travel documents
 *   - See a clear breakdown of what is paid vs outstanding
 *
 * No login required — the token IS the authentication.
 */

import { useState } from "react";
import {
  BadgeCheck,
  Calendar,
  CheckCircle2,
  CreditCard,
  Download,
  ExternalLink,
  FileText,
  Loader2,
  MapPin,
  Phone,
  Users,
  XCircle,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { useApiQuery } from "@/lib/api/hooks";
import { errorMessage, API_BASE_URL } from "@/lib/api/client";
import type { PortalBookingDto } from "@/lib/api/modules";

// ── Public API fetch (no bearer token, uses portal token in URL path) ─────────

async function fetchPortalBooking(token: string): Promise<PortalBookingDto> {
  const res = await fetch(`${API_BASE_URL}/portal/${token}`, {
    headers: { "Content-Type": "application/json" },
  });
  const body = (await res.json()) as { success: boolean; data: PortalBookingDto; error?: string };
  if (!body.success) throw new Error(body.error ?? "Failed to load booking");
  return body.data;
}

async function initiatePayment(token: string, invoiceId: string): Promise<string | null> {
  const res = await fetch(`${API_BASE_URL}/portal/${token}/pay`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ invoiceId }),
  });
  const body = (await res.json()) as {
    success: boolean;
    data: { paymentLink: string | null; message?: string };
  };
  if (!body.success) throw new Error("Payment initiation failed");
  return body.data.paymentLink;
}

// ── Currency formatter ────────────────────────────────────────────────────────

const fmt = (n: number, currency = "INR") =>
  new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(n);

// ── Status chip ───────────────────────────────────────────────────────────────

const STATUS_STYLES: Record<string, string> = {
  Confirmed: "bg-green-100 text-green-800",
  Pending: "bg-amber-100 text-amber-800",
  Cancelled: "bg-red-100 text-red-800",
  Completed: "bg-blue-100 text-blue-800",
};

// ── Component ─────────────────────────────────────────────────────────────────

export function CustomerPortal({ token }: { token: string }) {
  const {
    data: booking,
    loading,
    error,
  } = useApiQuery(() => fetchPortalBooking(token), [token], Boolean(token));

  const [payingId, setPayingId] = useState<string | null>(null);

  const handlePay = async (invoiceId: string) => {
    setPayingId(invoiceId);
    try {
      const link = await initiatePayment(token, invoiceId);
      if (link) {
        window.location.href = link;
      } else {
        toast.info("Online payment is not set up. Please contact your travel company.");
      }
    } catch (err) {
      toast.error(errorMessage(err, "Could not initiate payment"));
    } finally {
      setPayingId(null);
    }
  };

  // ── Loading state
  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-3 text-gray-500">
          <Loader2 className="size-10 animate-spin" />
          <p className="text-sm">Loading your booking…</p>
        </div>
      </div>
    );
  }

  // ── Error state
  if (error || !booking) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 p-4">
        <div className="w-full max-w-md rounded-2xl border border-red-200 bg-white p-8 text-center shadow-sm">
          <XCircle className="size-12 mx-auto text-red-400 mb-3" />
          <h1 className="text-lg font-bold text-gray-900">Link expired or invalid</h1>
          <p className="mt-2 text-sm text-gray-500">
            This booking link has expired or is no longer valid. Please contact your travel company
            for a new link.
          </p>
        </div>
      </div>
    );
  }

  const outstanding = booking.totalAmount - booking.paidAmount;
  const unpaidInvoices = booking.invoices.filter(
    (inv) => inv.status !== "paid" && inv.status !== "Paid",
  );

  return (
    <div className="min-h-screen bg-gray-50">
      {/* ── Header ────────────────────────────────────────────────────── */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-10">
        <div className="mx-auto max-w-2xl px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="size-8 rounded-lg bg-blue-600 flex items-center justify-center">
              <span className="text-white text-sm font-bold">T</span>
            </div>
            <span className="font-semibold text-gray-900 text-sm">Traveldesk</span>
          </div>
          <span className="text-xs text-gray-400">Booking #{booking.reference}</span>
        </div>
      </header>

      <main className="mx-auto max-w-2xl px-4 py-8 space-y-5">
        {/* ── Booking card ─────────────────────────────────────────────── */}
        <div className="rounded-2xl bg-white border border-gray-200 shadow-sm overflow-hidden">
          {/* Status banner */}
          <div className="bg-gradient-to-r from-blue-600 to-blue-700 px-6 py-5 text-white">
            <div className="flex items-start justify-between gap-3">
              <div>
                <p className="text-blue-200 text-xs font-medium uppercase tracking-wide mb-1">
                  Booking confirmation
                </p>
                <h1 className="text-xl font-bold">{booking.customerName}</h1>
              </div>
              <span
                className={cn(
                  "rounded-full px-3 py-1 text-xs font-semibold mt-1 whitespace-nowrap",
                  booking.status === "Confirmed"
                    ? "bg-green-400/20 text-white border border-green-300/30"
                    : "bg-white/20 text-white",
                )}
              >
                {booking.status}
              </span>
            </div>
          </div>

          <div className="px-6 py-5 grid gap-4 sm:grid-cols-2">
            {booking.destination && (
              <div className="flex items-start gap-3">
                <MapPin className="size-4 text-gray-400 mt-0.5 shrink-0" />
                <div>
                  <p className="text-[11px] text-gray-400 uppercase tracking-wide">Destination</p>
                  <p className="text-sm font-semibold text-gray-900">{booking.destination}</p>
                </div>
              </div>
            )}
            {booking.departureDate && (
              <div className="flex items-start gap-3">
                <Calendar className="size-4 text-gray-400 mt-0.5 shrink-0" />
                <div>
                  <p className="text-[11px] text-gray-400 uppercase tracking-wide">Travel dates</p>
                  <p className="text-sm font-semibold text-gray-900">
                    {new Date(booking.departureDate).toLocaleDateString("en-IN", {
                      day: "numeric",
                      month: "short",
                      year: "numeric",
                    })}
                    {booking.returnDate && (
                      <>
                        {" "}
                        —{" "}
                        {new Date(booking.returnDate).toLocaleDateString("en-IN", {
                          day: "numeric",
                          month: "short",
                          year: "numeric",
                        })}
                      </>
                    )}
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* ── Payment summary ──────────────────────────────────────────── */}
        <div className="rounded-2xl bg-white border border-gray-200 shadow-sm">
          <div className="px-6 py-4 border-b border-gray-100">
            <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
              <CreditCard className="size-4 text-gray-400" />
              Payment summary
            </h2>
          </div>
          <div className="px-6 py-4 grid gap-2">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Total amount</span>
              <span className="font-semibold">{fmt(booking.totalAmount, booking.currency)}</span>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Paid</span>
              <span className="font-semibold text-green-600">
                {fmt(booking.paidAmount, booking.currency)}
              </span>
            </div>
            {outstanding > 0 && (
              <div className="flex items-center justify-between text-sm border-t border-gray-100 pt-2 mt-1">
                <span className="font-semibold text-gray-900">Outstanding</span>
                <span className="font-bold text-red-600 text-base">
                  {fmt(outstanding, booking.currency)}
                </span>
              </div>
            )}
            {outstanding <= 0 && (
              <div className="flex items-center gap-2 rounded-xl bg-green-50 px-3 py-2 mt-1">
                <CheckCircle2 className="size-4 text-green-600 shrink-0" />
                <p className="text-sm font-medium text-green-700">Fully paid — thank you!</p>
              </div>
            )}
          </div>
        </div>

        {/* ── Invoices ─────────────────────────────────────────────────── */}
        {booking.invoices.length > 0 && (
          <div className="rounded-2xl bg-white border border-gray-200 shadow-sm">
            <div className="px-6 py-4 border-b border-gray-100">
              <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
                <FileText className="size-4 text-gray-400" />
                Invoices
              </h2>
            </div>
            <div className="divide-y divide-gray-100">
              {booking.invoices.map((inv) => {
                const isPaid = inv.status === "paid" || inv.status === "Paid";
                return (
                  <div key={inv.id} className="flex items-center justify-between gap-3 px-6 py-4">
                    <div>
                      <p className="text-sm font-medium text-gray-900">{inv.reference}</p>
                      <p className="text-xs text-gray-400 mt-0.5">
                        {fmt(inv.amount, booking.currency)}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      {isPaid ? (
                        <span className="inline-flex items-center gap-1 rounded-full bg-green-100 px-2.5 py-0.5 text-xs font-semibold text-green-700">
                          <CheckCircle2 className="size-3" /> Paid
                        </span>
                      ) : (
                        <button
                          onClick={() => void handlePay(inv.id)}
                          disabled={payingId === inv.id}
                          className="inline-flex items-center gap-1.5 rounded-xl bg-blue-600 px-4 py-2 text-xs font-semibold text-white hover:bg-blue-700 disabled:opacity-60 transition-colors"
                        >
                          {payingId === inv.id ? (
                            <Loader2 className="size-3 animate-spin" />
                          ) : (
                            <CreditCard className="size-3" />
                          )}
                          {payingId === inv.id ? "Loading…" : "Pay now"}
                        </button>
                      )}
                      {inv.paymentLink && (
                        <a
                          href={inv.paymentLink}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-gray-400 hover:text-blue-600"
                          title="Open payment link"
                        >
                          <ExternalLink className="size-4" />
                        </a>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ── Vouchers & documents ─────────────────────────────────────── */}
        {booking.vouchers.length > 0 && (
          <div className="rounded-2xl bg-white border border-gray-200 shadow-sm">
            <div className="px-6 py-4 border-b border-gray-100">
              <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
                <BadgeCheck className="size-4 text-gray-400" />
                Travel documents
              </h2>
            </div>
            <div className="divide-y divide-gray-100">
              {booking.vouchers.map((v) => (
                <div key={v.id} className="flex items-center justify-between gap-3 px-6 py-4">
                  <div>
                    <p className="text-sm font-medium text-gray-900">{v.reference}</p>
                    {v.checkIn && (
                      <p className="text-xs text-gray-400 mt-0.5">
                        {new Date(v.checkIn).toLocaleDateString("en-IN", {
                          day: "numeric",
                          month: "short",
                        })}
                        {v.checkOut && (
                          <>
                            {" "}
                            —{" "}
                            {new Date(v.checkOut).toLocaleDateString("en-IN", {
                              day: "numeric",
                              month: "short",
                              year: "numeric",
                            })}
                          </>
                        )}
                      </p>
                    )}
                  </div>
                  <a
                    href={`${API_BASE_URL.replace("/api/v1", "")}${v.downloadUrl}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1.5 rounded-xl border border-gray-200 px-3 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-50 transition-colors"
                  >
                    <Download className="size-3" />
                    Download
                  </a>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ── Footer ───────────────────────────────────────────────────── */}
        <div className="text-center text-xs text-gray-400 py-4">
          <p>Questions about your booking? Contact your travel company directly.</p>
          <p className="mt-1">Powered by Traveldesk</p>
        </div>
      </main>
    </div>
  );
}
